1	import peek from './peek.js';
2	
3	/**
4	 * Return the numerical span of an array: the difference between
5	 * the last and first values.
6	 */
7	export default function(array: readonly number[] | null | undefined): number {
8	  return array && (peek(array)! - array[0]) || 0;
